We have
\begin{equation} \label{eqn:l2}
D_{N,2}=\begin{cases}
0, & \mbox{if $N$ is even}\\
\left\lfloor \frac{N}{3} \right\rfloor+1, & \mbox{if $N$ is odd}.
\end{cases}
\end{equation}

In order to count the number of linearly independent such relations, we introduce the \textit{Fay-shuffle space} $\mathrm{FSh}_2(N)$
\footnote{Independently, this space has already been studied by Brown in an unpublished preprint, in a slightly different context \cite{BrownAnatomy}.}
in length two, which is an elliptic analogue of the (depth two) double-shuffle space defined in~\cite{IKZ} in the context of multiple zeta values.

We consider a version of the odd Jacobi theta function $\theta_{\tau}$, defined for $\xi \in \mathbb C$ by
\begin{equation}
\theta_{\tau}(\xi):=\sum_{n \in \mathbb Z}(-1)^nq^{\frac{1}{2}(n+\frac{1}{2})^2}e^{(n+\frac{1}{2})2\pi i\xi}, \quad q=e^{2\pi i\tau}.
\end{equation}

The \textit{Kronecker series} $F_{\tau}: \mathbb C \times \mathbb C \rightarrow \mathbb C$~\cite{W,Z} is the meromorphic function defined by the formula
\begin{equation}
F_{\tau}(\xi,\alpha)=\frac{\theta_{\tau}'(0)\theta_{\tau}(\xi+\alpha)}{\theta_{\tau}(\xi)\theta_{\tau}(\alpha)}.
\end{equation}

Consider the formal differential one-form (cf.~\cite{BL}, Section~3.5), where $\alpha$ is a formal variable
\begin{equation}
\Omega_{\tau}(\xi,\alpha):=e^{2\pi ir\alpha}F_{\tau}(\xi,\alpha)\mathrm{d} \xi.
\end{equation}

 \label{prop:kro}
The one-form $\Omega_{\tau}(\xi,\alpha)$ satisfies the following properties:
\begin{enumerate}
\item
It is doubly periodic in $\xi$:
\begin{align}
\Omega_{\tau}(\xi+1,\alpha)=\Omega_{\tau}(\xi,\alpha), \quad \Omega_{\tau}(\xi+\tau,\alpha)=\Omega_{\tau}(\xi,\alpha).
\end{align}
Thus it descends to a formal differential one-form on $E^{\times}_{\tau}$.
\item
It is symmetric in its arguments, i.e.
\begin{equation}
\Omega_{\tau}(-\xi,-\alpha)=\Omega_{\tau}(\xi,\alpha).
\end{equation}





\item
It satisfies the Fay identity:
\begin{align}
\Omega_{\tau}(\xi_1,\alpha_1) \land \Omega_{\tau}(\xi_2,\alpha_2)&=\Omega_{\tau}(\xi_1-\xi_2,\alpha_1) \land \Omega_{\tau}(\xi,\alpha_1+\alpha_2) \notag \\
&+\Omega_{\tau}(\xi_2-\xi_1,\alpha_2) \land \Omega_{\tau}(\xi,\alpha_1+\alpha_2).
\end{align}
\item
We have the modular transformation formula
\begin{equation} \label{eqn:Omegamod}
\Omega_{\frac{a\tau+b}{c\tau+d}}((c\tau+d)^{-1}\xi,(c\tau+d)^{-1}\alpha)=(c\tau+d)\Omega_{\tau}(\xi,\alpha)
\end{equation}
for $\begin{pmatrix}a&b\\c&d\end{pmatrix} \in \mathrm{SL}_2(\mathbb Z)$.
\end{enumerate}

Define a family $\{\omega^{(k)}\}_{k \geq 0}$ of real analytic differential one-forms on $E^{\times}_{\tau}$ by the formula
\begin{equation}
\Omega_{\tau}(\xi,\alpha)=\sum_{k \geq 0}\omega^{(k)}\alpha^{k-1}.
\end{equation}

Note that we have
\begin{equation}
\omega^{(k)}=f^{(k)}(\xi)\mathrm{d}\xi,
\end{equation}
where each $f^{(k)}$ is a real analytic function on $E^{\times}_{\tau}$.

 \label{cor:fk}
The form $\omega^{(k)}$ has modular weight $k+1$, i.e.
\begin{equation}
\omega^{(k)}_{\vert \gamma}=(c\tau+d)^{k+1}\omega^{(k)}
\end{equation}
where the action of $\gamma \in \mathrm{SL}_2(\mathbb Z)$ on $\omega^{(k)}$ is defined as in~\eqref{eqn:Omegamod}. Moreover, $\omega^{(k)}=f^{(k)}(\xi)\mathrm{d}\xi$ is doubly periodic and antisymmetric/symmetric depending on the weight
\begin{equation}
f^{(k)}(-\xi)=(-1)^kf^{(k)}(\xi),
\end{equation}
and we have the Fay identity
\begin{align}
f^{(m)}(\xi_1)f^{(n)}(\xi_2)&=-(-1)^nf^{(m+n)}(\xi_1-\xi_2) \notag\\
&+\sum_{r=0}^{n}\binom{m+r-1}{m-1}f^{(n-r)}(\xi_2-\xi_1)f^{(m+r)}(\xi_1) \notag\\
&+\sum_{r=0}^{m}\binom{n+r-1}{n-1}f^{(m-r)}(\xi_1-\xi_2)f^{(n+r)}(\xi_2).
\end{align}
\qed

Recall the definition of the Eisenstein series $G_{2k}(\tau)$ for $k \geq 1$, where $\sigma_m(n)=\sum_{d | n}d^m$ is the $m$-th divisor sum:
\begin{equation}
G_{2k}(\tau)=2\zeta(2k)+2\frac{(2\pi i)^{2k}}{(2k-1)!}\sum_{n \geq 1}\sigma_{2k-1}(n)q^n, \quad q=e^{2\pi i\tau}.
\end{equation}

 (\cite{MMV}, Example 4.10)
We define the \textit{indefinite Eisenstein integral} by
\begin{equation} \label{eqn:inteis}
{\mathcal G}_{2k}(\tau)=\int_{\tau}^{i\infty}G_{2k}(\tau')-2\zeta(2k)d\tau'+\int_0^{\tau}2\zeta(2k)d\tau'.
\end{equation}

 \label{prop:gradeis}
Let $\mathcal{E}\mathrm{is}_{2\pi i} \subset \mathcal O(\mathbb H)$ be the $\mathbb Q$-vector subspace spanned by all products
\begin{equation}
(2\pi i)^j{\mathcal G}_{2k}(\tau), \quad j,k \geq 0,
\end{equation}
and define a grading on $\mathcal{E}\mathrm{is}_{2\pi i}$ by giving $(2\pi i)^j{\mathcal G}_{2k}(\tau)$ weight $j+2k$. Then $\mathcal{E}\mathrm{is}_{2\pi i}$ is a graded $\mathbb Q$-vector space.

 \label{dfn:eMZV}
We define the A-elliptic multiple zeta value $I^A(n_1,\dots,n_r;\tau)$\footnote{In \cite{BMMS}, this is denoted by $\omega(n_1,...,n_r)$} to be the coefficient of $\mathrm{ad}^{n_1}(x)(y)\dots\mathrm{ad}^{n_r}(x)(y)$ in the regularized generating series
\begin{equation}
\lim_{t \to 0}(-2\pi it)^{\mathrm{ad}(x)(y)}\exp\bigg[\int_{\alpha_t^{1-t}}\mathrm{ad}(x)\Omega_{\tau}(\xi,\mathrm{ad}(x)(y))\bigg](-2\pi it)^{-\mathrm{ad}(x)(y)},
\end{equation}
where $\alpha_t^{1-t}$ denotes the restriction of the path $\alpha$ to the interval $[t,1-t]$, and for a differential one-form $\omega$, we write
\begin{equation}
\exp\bigg[\int \omega\bigg]=1+\sum_{k \geq 1}\int \underbrace{\omega\dots\omega}_{\textrm{k-times}}.
\end{equation}
The regularization of the integral is performed as in~\cite{Del}, Proposition 15.45 (with the order of integration reversed), with respect to the tangent vector $-\frac{\partial}{\partial z}=(-2\pi i)^{-1}\frac{\partial}{\partial \xi}$ at $0$ at the starting point of the path of integration (where $z=e^{2\pi i\xi}$), and with respect to the tangent vector $\frac{\partial}{\partial z}=(2\pi i)^{-1}\frac{\partial}{\partial \xi}$ at $0$ at the endpoint of the path of integration.

 \label{prop:compass}
For all $n_1,\dots,n_r \geq 0$, we have that $I^A(n_1,\dots,n_r;\tau)$ is equal to $(-1)^r$ times the coefficient of the word $\mathrm{ad}^{n_r}(x)(y)...\mathrm{ad}^{n_1}(x)(y)$ in the series
\begin{equation}
e^{-\pi i\mathrm{ad}(x)(y)}A(\tau),
\end{equation}
where $A(\tau)$ is Enriquez's A-associator (cf.~\cite{E2}, Section~5.2).

Recall that $A(\tau)$ is defined as
\begin{equation}
A(\tau)=X(z)^{-1}X(z+1),
\end{equation}
where $X(z)$ is the unique holomorphic function defined on $\{z \in \mathbb C \, | \, z=u+vi, \ u \mbox{ or } v \in (0,1)\} \subset \mathbb C$, which solves the equation 
\begin{equation}
\mathrm{d} X(z)=-\mathrm{ad}(x)\Omega_{\tau}(\xi,\mathrm{ad}(x))(y) \cdot X(z),
\end{equation}
and satisfies $X(z) \sim (-2\pi iz)^{-\mathrm{ad}(x)(y)}$, as $z \to 0$, where we choose the principal branch of the logarithm so that $\log(\pm i)=\pm \frac{\pi i}{2}$. Using Picard iteration, and standard properties of iterated integrals (cf.~Section~2.1), we see that $A(\tau)$ equals
\begin{align}
\bigg(\lim_{t \to 0}(-2\pi it)^{\mathrm{ad}(x)(y)}\exp\bigg[\int_{\alpha_t^{1-t}}(-\mathrm{ad}(x)\Omega_{\tau}(\xi,\mathrm{ad}(x)(y)))\bigg]e^{\pi i\mathrm{ad}(x)(y)}(-2\pi it)^{-\mathrm{ad}(x)(y)}\bigg)^{op},
\end{align}
where the superscript $op$ denotes the opposite multiplication on the algebra $\mathbb C \langle\langle x,y\rangle\rangle$, defined by $(f \cdot g)^{op}=g \cdot f$. Now multiplying by $e^{-\pi i\mathrm{ad}(x)(y)}$, the result follows.

In~\cite{E}, one also finds a notion of B-elliptic multiple zeta value, which we denote here by $I^B(n_1,\dots,n_r;\tau)$, defined as iterated integrals along the other homology cycle $\beta$ of an elliptic curve. Similar to A-elliptic multiple zeta values, B-elliptic multiple zeta values can be obtained as coefficients of Enriquez's B-associator~\cite{E2}. The modular transformation formula (cf.~\cite{E}, eq.~(26))
\begin{equation}
I^B(n_1,\dots,n_r;\tau)=\tau^{-(n_1+\dots+n_r)+r}I^A(n_1,\dots,n_r;-\tau^{-1})
\end{equation}
establishes a close connection between A-elliptic and B-elliptic multiple zeta values. A more detailed treatment of B-elliptic multiple zeta values will be given elsewhere.

By Proposition~5.3 of~\cite{E}, every A-elliptic multiple zeta value has a Fourier expansion
\begin{equation}
\sum_{k \geq 0}a_kq^k, \quad q=e^{2\pi i\tau},
\end{equation}
with the coefficients $a_k$ contained in $\mathcal{Z}[(2\pi i)^{-1}]$, where $\mathcal{Z}$ denotes the $\mathbb Q$-algebra of multiple zeta values.

 \label{prop:constterm}
Denote by $c_{n_1,\dots,n_r}$ the constant term in the Fourier expansion of $I^A(n_1,\dots,n_r;\tau)$. It is
\begin{equation}
c_n=
\begin{cases}
0 ,& \mbox{for $n=1$}\\
\frac{B_n}{n!}(2\pi i)^n, & \mbox{else},
\end{cases}
\end{equation}
and
\begin{equation}
c_{m,n}=
\begin{cases}
0, & \mbox{if $m=n=1$}\\
-\frac 12 (2\pi i)^{m+1}\frac{B_mB_1}{m!},  & \mbox{if $n=1$ and $m \neq 1$}\\
\frac 12 (2\pi i)^{m+n}\frac{B_mB_n}{m!n!} ,& \mbox{else},
\end{cases}
\end{equation}
where $B_n$ are the Bernoulli numbers defined by the series $\sum_{n \geq 0}\frac{B_n}{n!}t^n=\frac{t}{e^t-1}$.

By~\cite{E} (cf.~also~\cite{BMS}, eq.~(2.43)), we have
\begin{equation} \label{eqn:constterm}
\lim_{\tau \to i\infty} e^{\pi it}A(\tau)=e^{\pi it}\Phi(\tilde{y},t)e^{2\pi i\tilde{y}}\Phi(\tilde{y},t)^{-1},
\end{equation}
where $t=-\mathrm{ad}(x)(y)$ and $\tilde{y}=-\frac{\mathrm{ad}(x)}{e^{2\pi i\mathrm{ad}(x)}-1}(y)$. Now by Proposition \ref{prop:compass}, we see that $c_{n_1,\dots,n_r}$ is given by the coefficient of $(-1)^r\mathrm{ad}^{n_r}(x)(y)\dots\mathrm{ad}^{n_1}(x)(y)$ on the left hand side of \eqref{eqn:constterm}, and the result follows by comparing coefficients.

This is non-trivial, since the differential forms $\omega^{(k)}$ are not closed for $k \geq 1$, and thus already the value of the ordinary line integral
\begin{equation}
\int_{\gamma}\omega^{(k)}, \quad k \geq 1
\end{equation}
is not invariant under homotopies of the path $\gamma$.

The fundamental result we will need is the following.

 \label{thm:BL}
Every homotopy invariant iterated integral on $E^{\times}_{\tau}$ is a $\mathbb C$-linear combination of coefficients of the words $x,y$ in the generating series
\begin{equation} \label{eqn:geniter}
T=1+\sum_{k \geq 1}\int \underbrace{J\dots J}_{\textrm{k-times}},
\end{equation}
where 
\begin{equation} \label{eqn:kzbeqn}
J=-\nu x+\mathrm{ad}(x)\Omega_{\tau}(\xi,\mathrm{ad}(x))(y)=-\nu x+\sum_{k \geq 0}\omega^{(k)}\mathrm{ad}^k(x)(y)
\end{equation} 
with $\nu=2\pi i \mathrm{d} r$.

Since every coefficient of $T$ is a homotopy invariant iterated integral, for any pair of points $\xi,\rho \in E^{\times}_{\tau}$, we can consider $T$ as a function
\begin{align}
T(\_ ): \pi_1(E^{\times}_{\tau};\xi,\rho) &\rightarrow \mathbb C\langle\langle x,y\rangle\rangle\\
\gamma &\mapsto T(\gamma),
\end{align}
where $T(\gamma)$ denotes integration of $T$ along the path $\gamma$.

We use induction on the set of multi-indices of a fixed length $r$, ordered lexicographically. For $\underline{n}=(0,\dots,0) \in \mathbb N^r$, it is clear that
\begin{equation}
I^A(0,\dots,0;\tau)=T^{\mathrm{Reg}}(\alpha)_{y^r}.
\end{equation}
Now let $\underline{n}=(n_1,\dots,n_r)$ be a multi-index of length $r$ and assume the proposition for all multi-indices $\underline{n'}$ such that $\underline{n'} \prec \underline{n}$ in the lexicographical ordering. Now by \eqref{eqn:transl}, we have
\begin{equation}
I^A(\underline{n};\tau)=(-1)^{n_1+\dots+n_r}\left(T^{\mathrm{Reg}}(\alpha)_w-\sum_{\underline{n'} \prec \underline{n}} c_{\underline{n'}}I^A(\underline{n'};\tau) \right),
\end{equation}
where $w=yx^{n_1}\dots yx^{n_r}$. The terms on the right hand side of the last equation can be expressed as coefficients of $T^{\mathrm{Reg}}(\alpha)$, by the induction hypothesis, and this ends the proof.

 \label{thm:diff}
For all $r \geq 0$, we have
\begin{align} \label{eqn:diffenr}
2\pi i\frac{\partial}{\partial \tau}{\mathcal I}^A(X_1,\dots,X_r;\tau)&=\wp_{\tau}^*(X_1){\mathcal I}^A(X_2,\dots,X_r;\tau)-\wp_{\tau}^*(X_r){\mathcal I}^A(X_1,\dots,X_{r-1};\tau) \notag\\
&+\sum_{i=1}^{r-1}(\wp_{\tau}^*(X_{i+1})-\wp_{\tau}^*(X_i)){\mathcal I}^A(X_1,\dots,X_i+X_{i+1},\dots,X_r;\tau),
\end{align}
where $\wp_{\tau}^*(\alpha)=\sum_{k=-1}^{\infty}(2k+1)G_{2k+2}(\tau)\alpha^{2k}$ considered as a formal power series in $\alpha$.






\qed

 \label{cor:diff}


Elliptic multiple zeta values of length one are constant, i.e.
\begin{equation} \label{eqn:cor1}
2\pi i\frac{\partial}{\partial \tau}I^A(n;\tau)=0.
\end{equation}
More precisely, writing $I^A(n)$ instead of $I^A(n;\tau)$, we have $I^A(1)=0$ and
\begin{equation} \label{eqn:cor1b}
I^A(n)=\frac{(2\pi i)^nB_n}{n!}, \quad n \neq 1.
\end{equation}

In length two, we have
\begin{align} \label{eqn:cor2a}
2\pi i\frac{\partial}{\partial \tau}I^A(0,n;\tau)&=(-1)^n2\pi i\frac{\partial}{\partial \tau}I^A(n,0;\tau) \notag \\
&=-nG_{n+1}(\tau)I^A(0)+nG_0(\tau)I^A(n+1),
\end{align}
and if $m,n \neq 0$
\begin{align} \label{eqn:cor2b}
2\pi i\frac{\partial}{\partial \tau}I^A(m,n;\tau)&=-nG_{n+1}(\tau)I^A(m)+mG_{m+1}(\tau)I^A(n) \notag \\
&-(-1)^m(m+n)G_{m+n+1}(\tau)I^A(0) \notag \\
&+\sum_{k=1}^{m+n+1}(m+n-k)\left( \binom{k-1}{m-1}-\binom{k-1}{n-1} \right)G_{m+n+1-k}(\tau)I^A(k),
\end{align}
where we recall that by definition $G_n(\tau) \equiv 0$ whenever $n$ is odd. In particular, $\frac{\partial}{\partial \tau}I^A(m,n;\tau)=0$ if $m+n$ is even, and is given by
\begin{equation} \label{eqn:cor2c}
I^A(m,n;\tau)=\frac{(2\pi i)^{m+n}}{2} \frac{B_mB_n}{m!n!}.
\end{equation}

 \label{prop:Qrel}
For all $m,n \geq 0$, we have the following relations between elliptic double zeta values:
\begin{enumerate}
\item (Reflection relation)
\begin{equation}
I^A(m,n;\tau)=(-1)^{m+n}I^A(n,m;\tau)
\end{equation}
\item (Shuffle relation)
\begin{equation}
I^A(m,n;\tau)+I^A(n,m;\tau)=I^A(m)I^A(n)
\end{equation}




\item (Fay relation)
\begin{align}
I^A(m,n;\tau)&=-\delta_{m,1}\delta_{n,1}3\zeta(2)-(-1)^nI^A(0,m+n;\tau) \notag\\
&+\sum_{r=0}^n(-1)^{n-r}\binom{m-1+r}{m-1}I^A(m+r,n-r;\tau) \notag \\
&+\sum_{r=0}^m(-1)^{n+r}\binom{n-1+r}{n-1}I^A(n+r,m-r;\tau)
\end{align}
\end{enumerate}

