Define the $\mathbb Q$-vector space of A-elliptic multiple zeta values to be
\begin{equation}
\mathcal{EZ}^A=\langle I^A(n_1,\dots,n_r;\tau) \, \vert \, n_1,\dots,n_r \geq 0 \rangle_{\mathbb Q} \subset \mathcal O(\mathbb H).
\end{equation}
Also, we define its weight $N$ component to be
\begin{equation}
\mathcal{EZ}^A_N=\langle I^A(n_1,\dots,n_r;\tau) \, \vert \, n_1+\dots +n_r=N \rangle_{\mathbb Q} \subset \mathcal O(\mathbb H).
\end{equation}

By definition, $\mathcal{EZ}^A$ is linearly spanned by the coefficients of the series
\begin{equation} \label{eqn:genseries}
\lim_{t \to 0}(-2\pi it)^{\mathrm{ad}(x)(y)}\exp\bigg[\int_{\alpha_t^{1-t}}\mathrm{ad}(x)\Omega_{\tau}(\xi,\mathrm{ad}(x)(y))\bigg](-2\pi it)^{-\mathrm{ad}(x)(y)}.
\end{equation}
By \eqref{eqn:comp}, the series \eqref{eqn:genseries} is group-like for the unique coproduct on $\mathbb C \langle \langle x,y \rangle \rangle$ for which $x$ and $y$ are primitive, which is equivalent to its coefficients satisfying the shuffle product formula. But since the elements $\mathrm{ad}^n(x)(y)$ are also primitive, the proposition follows.

We denote by
\begin{equation}
\mathcal{L}_l\mathcal{EZ}^A_N=\langle I^A(n_1,\dots,n_r;\tau) \in \mathcal{EZ}^A_N \, \vert \, r \leq l \rangle_{\mathbb Q}
\end{equation}
the $\mathbb Q$-subspace of A-elliptic multiple zeta values of weight $N$ and of length at most $l$. We also denote by
\begin{equation}
\mathrm{gr}^{\mathcal{L}}_l\mathcal{EZ}^A_N
\end{equation}
the associated graded.

$\mathcal{EZ}^A$ is a filtered $\mathbb Q$-algebra for the length filtration. More precisely, the multiplication law on $\mathcal{EZ}^A$ satisfies
\begin{equation}
\mathcal{L}_l\mathcal{EZ}^A_N \cdot \mathcal{L}_{l'}\mathcal{EZ}^A_{N'} \subset \mathcal{L}_{l+l'}\mathcal{EZ}^A_{N+N'},
\end{equation}
for all $l,l',N,N' \geq 0$.

 \label{conj:weight}
$\mathcal{EZ}^A$ is graded for the weight, i.e. the natural morphism
\begin{align}
\bigoplus_{N \geq 0} \mathcal{EZ}^A_N &\rightarrow \mathcal O(\mathbb H)\\
(I^A_N)_{N \geq 0} &\mapsto \sum_{N \geq 0} I^A_N,
\end{align}
with $I^A_N \in \mathcal{EZ}^A_N$, induced by the inclusions $\mathcal{EZ}^A_N \subset \mathcal O(\mathbb H)$, is injective.

