 \label{thm:linind}
Let $N > 0$ be odd, and $k=\lfloor \frac N3 \rfloor$.
\begin{enumerate}
\item
The set
\begin{equation}
{\mathcal B}_{N,2}=\left\{\frac{\partial}{\partial \tau} I^A(r,N-r;\tau) \; \vert \; 0 \leq r \leq k \right\}
\end{equation}
is linearly independent over $\mathbb Q$.
\item
We have 
\begin{equation}
\dim_{\mathbb Q}\mathcal{L}_2\mathcal{EZ}^A_N \geq \left\lfloor \frac N3 \right\rfloor+1.
\end{equation}
\end{enumerate}

First note that i) implies ii), as the A-elliptic double zeta values $I^A(r,N-r)$ for $r=0,\dots,k$ are linearly independent, since, by i), their derivatives are.

So assume there exists a relation
\begin{align} \label{eqn:diffrel}
\sum_{r=0}^k\lambda_r\frac{\partial}{\partial \tau}I^A(r,N-r;\tau)=0.
\end{align}
with $\lambda_r \in \mathbb Q$ for $r=0,\dots,k$. Then
\begin{align} \label{eqn:prematrix}
0=\lambda_0(NG_{0}(\tau)I^A(N)&-NG_{N+1}(\tau)I^A(0))+\sum_{r=1}^k\lambda_r\bigg(-(N-r)G_{N-r+1}(\tau)I^A(r) \notag\\
&+rG_{r+1}(\tau)I^A(N-r)-(-1)^rNG_{N+1}(\tau)I^A(0) \notag\\
&+\sum_{s=1}^{N+1}(N-s)\left(\binom{s-1}{r-1}-\binom{s-1}{N-r-1}\right)G_{N+1-s}(\tau)I^A(s)\bigg),
\end{align}
by Corollary \ref{cor:diff}. Denote by $C_N$ the $(k+1) \times (N+3)/2$ matrix whose entry $(C_N)_{r,s}$ is given by
\begin{equation}
(C_N)_{r,s}=\mbox{Coefficient of $\lambda_rI^A(2s)G_{N+1-2s}(\tau)$ in \eqref{eqn:prematrix}}.
\end{equation}
Since the Eisenstein series are linearly independent over $\mathbb C$, the existence of rational numbers $\lambda_0,\dots,\lambda_k$ solving \eqref{eqn:diffrel} is equivalent to the row vector $\Lambda_N:=(\lambda_0,\dots,\lambda_k) \in \mathbb Q^{k+1}$ solving
\begin{equation} \label{eqn:mat}
\Lambda_N \cdot C_N=(0,\dots,0).
\end{equation}
Thus if we can prove that the rank of $C_N$ is at least $k+1$, we are done, because then \eqref{eqn:mat} has only the trivial solution. Also, note that the first row of $C_N$ is equal to $(-N,0,\dots,0,N)$ by \eqref{eqn:prematrix}. Therefore, if we can prove that among the columns of $C_N$ indexed by $s=1,\dots,(N-1)/2$, there are $k$ linearly independent ones, $C_N$ will have rank at least $k+1$. For this, we can clearly assume that $N \geq 3$.

To this end, consider, for $N \geq 3$ and $N$ odd, the square submatrix $C'_N$ of $C_N$ consisting of the columns $s=1,2,\dots,k$. Looking at \eqref{eqn:prematrix} and comparing with Corollary \ref{cor:diff}, we see that its entries are given by
\begin{align} 
c'_{N;i,j}=(N-2j-2)\left(\binom{2j+1}{i}-\delta_{2j+1,i}\right), \quad 0 \leq i,j \leq k-1.
\end{align}
Since $N-2j-2 \neq 0$ for every $j$, as $N$ is odd, it is enough to prove that the scaled matrix $M_{k-1}=(m_{i,j})$ with
\begin{equation}
m_{i,j}=\left(\binom{2j+1}{i}-\delta_{2j+1,i}\right), \quad 0 \leq i,j \leq k-1
\end{equation}
is invertible for every $k \geq 1$, which is proved in the appendix (Proposition \ref{prop:app}).

From Theorem \ref{thm:Fayshuf}, we know that, if $N$ is even 
\begin{equation}
\dim_{\mathbb Q} \mathrm{gr}^{\mathcal{L}}_2\mathcal{EZ}^A_N \leq \dim_{\mathbb Q}\mathrm{FSh}_2(N)=0,
\end{equation}
which proves the theorem in that case.

For odd $N$, we know by Theorem \ref{thm:Fayshuf}, using that $\mathcal{L}_1\mathcal{EZ}^A_N=0$ if $N$ is odd,
\begin{equation}
\dim_{\mathbb Q}\mathrm{gr}^{\mathcal{L}}_2\mathcal{EZ}^A_N \leq \left\lfloor \frac N3 \right\rfloor+1.
\end{equation}
On the other hand, by Theorem \ref{thm:linind}, the elliptic double zeta values
\begin{equation}
I^A(r,N-r;\tau) \quad 0 \leq r \leq k,
\end{equation}
where $k=\lfloor \frac N3 \rfloor$, are linearly independent over $\mathbb Q$. Therefore we have
\begin{equation}
\dim_{\mathbb Q}\mathrm{gr}^{\mathcal{L}}_2\mathcal{EZ}^A_N = \left\lfloor \frac N3 \right\rfloor+1,
\end{equation}
if $N$ is odd.
Finally, the map
\begin{align}
\mathrm{FSh}_2(N)^* &\rightarrow \mathrm{gr}^{\mathcal{L}}_2\mathcal{EZ}^A_N \notag\\
(X^*)^{k-1}(Y^*)^{l-1} &\mapsto I^A(k,l;\tau) \mod \mathcal{L}_1\mathcal{EZ}^A_N
